     "kolorea": "laranja",
     "titulua": null,
     "blokeak": [
      {
       "mota": "testua",
       "html": "<math display=\"block\"><mrow><msup><mi>t</mi><mn>2</mn></msup><mover><mi>y</mi><mo accent=\"true\">̈</mo></mover><mo>+</mo><mi>t</mi><mover><mi>y</mi><mo accent=\"true\">̇</mo></mover><mo>+</mo><msup><mi>t</mi><mn>2</mn></msup><mi>y</mi><mo>=</mo><mn>0</mn><mi>.</mi></mrow></math>"
      }
     ]
